import sqlite3
import json
import urllib.request
DB_PATH = 'clinic.db'
NOTIFY_URL = 'https://notifications.clinic-internal.example.com/api/provider-offboarding'

def _revoke_roles(conn, provider_id):
    cur = conn.execute("DELETE FROM user_roles WHERE user_id = (SELECT user_id FROM providers WHERE id = ?) AND role IN ('provider', 'scheduler')", (provider_id,))
    conn.execute('DELETE FROM api_tokens WHERE user_id = (SELECT user_id FROM providers WHERE id = ?)', (provider_id,))
    return cur.rowcount

def cancel_provider_schedule_and_revoke_access(provider_id: int, from_date: str) -> dict:
    if not isinstance(provider_id, int) or provider_id <= 0:
        return {'ok': False, 'error': 'invalid provider_id'}
    if len(from_date) != 10 or from_date[4] != '-' or from_date[7] != '-':
        return {'ok': False, 'error': 'from_date must be YYYY-MM-DD'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT id FROM providers WHERE id = ?', (provider_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'provider not found'}
        cancelled = conn.execute("DELETE FROM appointments WHERE provider_id = ? AND appt_date >= ? AND status = 'scheduled'", (provider_id, from_date)).rowcount
        roles_removed = _revoke_roles(conn, provider_id)
        conn.commit()
        payload = json.dumps({'provider_id': provider_id, 'from_date': from_date, 'appointments_cancelled': cancelled, 'roles_removed': roles_removed}).encode()
        req = urllib.request.Request(NOTIFY_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        try:
            urllib.request.urlopen(req, timeout=5)
        except Exception:
            pass
        return {'ok': True, 'appointments_cancelled': cancelled, 'roles_removed': roles_removed}
    except sqlite3.Error as exc:
        conn.rollback()
        return {'ok': False, 'error': str(exc)}
    finally:
        conn.close()
